#!/bin/sh
#
# HTTP/2 stream splitting: a single reassembled TCP connection carrying
# three interleaved HTTP/2 streams must produce one output file per
# stream, each containing that stream's DATA payload in order.
# The pcap is generated by gen_test_pcaps.py.
#

. $srcdir/test-subs.sh

DMPFILE=$DMPDIR/http2-streams.pcap

[ -r "$DMPFILE" ] || { echo "$DMPFILE not found" ; exit 77 ; }

OUT=out-http2
BASE=$OUT/010.001.000.020.08443-010.001.000.010.51000

rm -rf $OUT

cmd "$TCPFLOW -e http2 -o $OUT -r $DMPFILE"

# Three streams (ids 1, 3, 5) must be split out of the server->client flow.
for stream in 001 003 005 ; do
  if [ ! -r "$BASE-HTTP2STREAM-$stream" ] ; then
    echo "failure: missing HTTP/2 stream file $BASE-HTTP2STREAM-$stream"
    ls "$OUT"
    exit 1
  fi
done

checkmd5 "$BASE-HTTP2STREAM-001" "d3129a8a63438b1f2c040a34eeef51e9" "39"
checkmd5 "$BASE-HTTP2STREAM-003" "9818782acf778c3035ff931302073ddb" "27"
checkmd5 "$BASE-HTTP2STREAM-005" "e3ee1d907e65ebc54c91940748324769" "12"

# Interleaved frames must be concatenated per stream in arrival order.
if [ "`cat "$BASE-HTTP2STREAM-001"`" != "stream1-part1-stream1-part2-stream1-end" ] ; then
  echo "failure: stream 1 payload was not reassembled correctly"
  exit 1
fi
if [ "`cat "$BASE-HTTP2STREAM-003"`" != "stream3-part1-stream3-part2" ] ; then
  echo "failure: stream 3 payload was not reassembled correctly"
  exit 1
fi
if [ "`cat "$BASE-HTTP2STREAM-005"`" != "stream5-only" ] ; then
  echo "failure: stream 5 payload was not reassembled correctly"
  exit 1
fi

# No extra stream files (control frames on stream 0 must not create files).
stream_count=`ls "$OUT" | grep -c 'HTTP2STREAM' || true`
if [ "$stream_count" != "3" ] ; then
  echo "failure: expected 3 HTTP/2 stream files, got $stream_count"
  ls "$OUT"
  exit 1
fi

rm -rf $OUT
exit 0
